    @staticmethod
    def to_jwk(key_obj: AllowedRSAKeys, as_dict: Literal[True]) -> JWKDict:
        ...  # pragma: no cover

    @overload
    @staticmethod
    def to_jwk(key_obj: AllowedRSAKeys, as_dict: Literal[False] = False) -> str:
        ...  # pragma: no cover

    @staticmethod
    def to_jwk(
        key_obj: AllowedRSAKeys, as_dict: bool = False
    ) -> Union[JWKDict, str]:
        obj: dict[str, Any] | None = None

        if hasattr(key_obj, "private_numbers"):
            # Private key
            numbers = key_obj.private_numbers()

            obj = {
                "kty": "RSA",
                "key_ops": ["sign"],
                "n": to_base64url_uint(numbers.public_numbers.n).decode(),
                "e": to_base64url_uint(numbers.public_numbers.e).decode(),
                "d": to_base64url_uint(numbers.d).decode(),
                "p": to_base64url_uint(numbers.p).decode(),
                "q": to_base64url_uint(numbers.q).decode(),
                "dp": to_base64url_uint(numbers.dmp1).decode(),
                "dq": to_base64url_uint(numbers.dmq1).decode(),
                "qi": to_base64url_uint(numbers.iqmp).decode(),
            }

        elif hasattr(key_obj, "verify"):
            # Public key
            numbers = key_obj.public_numbers()

            obj = {
                "kty": "RSA",
                "key_ops": ["verify"],
                "n": to_base64url_uint(numbers.n).decode(),
                "e": to_base64url_uint(numbers.e).decode(),
            }
        else:
            raise InvalidKeyError("Not a public or private key")

        if as_dict:
            return obj
        else:
            return json.dumps(obj)

    @staticmethod
    def from_jwk(jwk: str | JWKDict) -> AllowedRSAKeys:
        try:
            if isinstance(jwk, str):
                obj = json.loads(jwk)
            elif isinstance(jwk, dict):
                obj = jwk
            else:
                raise ValueError
        except ValueError:
            raise InvalidKeyError("Key is not valid JSON")

        if obj.get("kty") != "RSA":
            raise InvalidKeyError("Not an RSA key")

        if "d" in obj and "e" in obj and "n" in obj:
            # Private key
            if "oth" in obj:
                raise InvalidKeyError(
                    "Unsupported RSA private key: > 2 primes not supported"
                )

            other_props = ["p", "q", "dp", "dq", "qi"]
            props_found = [prop in obj for prop in other_props]
            any_props_found = any(props_found)

            if any_props_found and not all(props_found):
                raise InvalidKeyError(
                    "RSA key must include all parameters if any are present besides d"
                )

            public_numbers = RSAPublicNumbers(
                from_base64url_uint(obj["e"]),
                from_base64url_uint(obj["n"]),
            )

            if any_props_found:
                numbers = RSAPrivateNumbers(
                    d=from_base64url_uint(obj["d"]),
                    p=from_base64url_uint(obj["p"]),
                    q=from_base64url_uint(obj["q"]),
                    dmp1=from_base64url_uint(obj["dp"]),
                    dmq1=from_base64url_uint(obj["dq"]),
                    iqmp=from_base64url_uint(obj["qi"]),
                    public_numbers=public_numbers,
                )
            else:
                d = from_base64url_uint(obj["d"])
                p, q = rsa_recover_prime_factors(
                    public_numbers.n, d, public_numbers.e
                )

                numbers = RSAPrivateNumbers(
                    d=d,
                    p=p,
                    q=q,
                    dmp1=rsa_crt_dmp1(d, p),
                    dmq1=rsa_crt_dmq1(d, q),
                    iqmp=rsa_crt_iqmp(p, q),
                    public_numbers=public_numbers,
                )

            return numbers.private_key()
        elif "n" in obj and "e" in obj:
            # Public key
            return RSAPublicNumbers(
                from_base64url_uint(obj["e"]),
                from_base64url_uint(obj["n"]),
            ).public_key()
        else:
            raise InvalidKeyError("Not a public or private key")

    def sign(self, msg: bytes, key: RSAPrivateKey) -> bytes:
        return key.sign(msg, padding.PKCS1v15(), self.hash_alg())

    def verify(self, msg: bytes, key: RSAPublicKey, sig: bytes) -> bool:
        try:
            key.verify(sig, msg, padding.PKCS1v15(), self.hash_alg())
            return True
        except InvalidSignature:
            return False

def from_jwk(jwk: str | JWKDict) -> AllowedECKeys:
    try:
        if isinstance(jwk, str):
            obj = json.loads(jwk)
        elif isinstance(jwk, dict):
            obj = jwk
        else:
            raise ValueError
    except ValueError:
        raise InvalidKeyError("Key is not valid JSON")

    if obj.get("kty") != "EC":
        raise InvalidKeyError("Not an Elliptic curve key")

    if "x" not in obj or "y" not in obj:
        raise InvalidKeyError("Not an Elliptic curve key")

    x = base64url_decode(obj.get("x"))
    y = base64url_decode(obj.get("y"))

    curve = obj.get("crv")
    curve_obj: EllipticCurve

    if curve == "P-256":
        if len(x) == len(y) == 32:
            curve_obj = SECP256R1()
        else:
            raise InvalidKeyError("Coords should be 32 bytes for curve P-256")
    elif curve == "P-384":
        if len(x) == len(y) == 48:
            curve_obj = SECP384R1()
        else:
            raise InvalidKeyError("Coords should be 48 bytes for curve P-384")
    elif curve == "P-521":
        if len(x) == len(y) == 66:
            curve_obj = SECP521R1()
        else:
            raise InvalidKeyError("Coords should be 66 bytes for curve P-521")
    elif curve == "secp256k1":
        if len(x) == len(y) == 32:
            curve_obj = SECP256K1()
        else:
            raise InvalidKeyError(
                "Coords should be 32 bytes for curve secp256k1"
            )
    else:
        raise InvalidKeyError(f"Invalid curve: {curve}")

    public_numbers = EllipticCurvePublicNumbers(
        x=int.from_bytes(x, byteorder="big"),
        y=int.from_bytes(y, byteorder="big"),
        curve=curve_obj,
    )

    if "d" not in obj:
        return public_numbers.public_key()

    d = base64url_decode(obj.get("d"))
    if len(d) != len(x):
        raise InvalidKeyError(
            "D should be {} bytes for curve {}", len(x), curve
        )

    return EllipticCurvePrivateNumbers(
        int.from_bytes(d, byteorder="big"), public_numbers
    ).private_key()

class ECAlgorithm(Algorithm):
    """
    Performs signing and verification operations using
    ECDSA and the specified hash function
    """

    SHA256: ClassVar[type[hashes.HashAlgorithm]] = hashes.SHA256
    SHA384: ClassVar[type[hashes.HashAlgorithm]] = hashes.SHA384
    SHA512: ClassVar[type[hashes.HashAlgorithm]] = hashes.SHA512

    def __init__(self, hash_alg: type[hashes.HashAlgorithm]) -> None:
        self.hash_alg = hash_alg

    def prepare_key(self, key: AllowedECKeys | str | bytes) -> AllowedECKeys:
        if isinstance(key, (EllipticCurvePrivateKey, EllipticCurvePublicKey)):
            return key

        if not isinstance(key, (bytes, str)):
            raise TypeError("Expecting a PEM-formatted key.")

        key_bytes = force_bytes(key)

        # Attempt to load key. We don't know if it's
        # a Signing Key or a Verifying Key, so we try
        # the Verifying Key first.
        try:
            if key_bytes.startswith(b"ecdsa-sha2-"):
                crypto_key = load_ssh_public_key(key_bytes)
            else:
                crypto_key = load_pem_public_key(key_bytes)  # type: ignore[assignment]
        except ValueError:
            crypto_key = load_pem_private_key(key_bytes, password=None)  # type: ignore[assignment]

        # Explicit check the key to prevent confusing errors from cryptography
        if not isinstance(
            crypto_key, (EllipticCurvePrivateKey, EllipticCurvePublicKey)
        ):
            raise InvalidKeyError(
                "Expecting a EllipticCurvePrivateKey/EllipticCurvePublicKey. Wrong key provided for ECDSA algorithms"
            )

        return crypto_key

    def sign(self, msg: bytes, key: EllipticCurvePrivateKey) -> bytes:
        der_sig = key.sign(msg, ECDSA(self.hash_alg()))

        return der_to_raw_signature(der_sig, key.curve)

    def verify(self, msg: bytes, key: "AllowedECKeys", sig: bytes) -> bool:
        try:
            der_sig = raw_to_der_signature(sig, key.curve)
        except ValueError:
            return False

        try:
            public_key = (
                key.public_key()
                if isinstance(key, EllipticCurvePrivateKey)
                else key
            )
            public_key.verify(der_sig, msg, ECDSA(self.hash_alg()))
            return True
        except InvalidSignature:
            return False

